  EnglishWord(word: 'Explicit', partOfSpeech: 'adjective', definition: 'Stated clearly and in detail, leaving no room for confusion or doubt.', example: 'The statute contains an explicit prohibition against retrospective application.', synonyms: ['clear', 'unambiguous', 'definite']),
  EnglishWord(word: 'Expunge', partOfSpeech: 'verb', definition: 'To erase or remove completely; to obliterate.', example: 'The court ordered the defamatory remarks to be expunged from the record.', synonyms: ['erase', 'delete', 'remove']),
