  EnglishWord(word: 'Fabricate', partOfSpeech: 'verb', definition: 'To invent or concoct something, typically with deceitful intent.', example: 'The evidence was fabricated to falsely implicate the accused.', synonyms: ['forge', 'falsify', 'concoct']),
