  EnglishWord(word: 'Flagrant', partOfSpeech: 'adjective', definition: 'Conspicuously or obviously offensive; glaringly bad.', example: 'The action was held to be a flagrant violation of fundamental rights.', synonyms: ['blatant', 'glaring', 'egregious']),
  EnglishWord(word: 'Foreclose', partOfSpeech: 'verb', definition: 'To rule out or prevent; to take possession of a mortgaged property.', example: 'The bank moved to foreclose on the mortgaged property after default.', synonyms: ['prevent', 'preclude', 'seize']),
  EnglishWord(word: 'Forfeit', partOfSpeech: 'verb/noun', definition: 'To lose or be deprived of property or a right as a penalty.', example: 'The bail bond was forfeited when the accused absconded.', synonyms: ['lose', 'surrender', 'give up']),
