  EnglishWord(word: 'Garnish', partOfSpeech: 'verb', definition: 'In law, to seize money or property to satisfy a debt through legal process.', example: 'The court issued a garnishee order attaching the debtor\'s bank account.', synonyms: ['attach', 'seize', 'levy']),
  EnglishWord(word: 'Gratuitous', partOfSpeech: 'adjective', definition: 'Done without good reason; uncalled for. Also: given or done free of charge.', example: 'A gratuitous promise without consideration is not enforceable.', synonyms: ['unwarranted', 'unjustified', 'free']),
  EnglishWord(word: 'Grievance', partOfSpeech: 'noun', definition: 'A real or imagined cause for complaint; a wrong considered as grounds for complaint.', example: 'The petitioner\'s grievance is that his service conditions were altered without notice.', synonyms: ['complaint', 'wrong', 'injustice']),
  EnglishWord(word: 'Groundless', partOfSpeech: 'adjective', definition: 'Not based on any good reason; without foundation.', example: 'The allegations were found to be groundless and motivated by malice.', synonyms: ['baseless', 'unfounded', 'unsubstantiated']),

