  EnglishWord(word: 'Heinous', partOfSpeech: 'adjective', definition: 'Utterly odious or wicked; shockingly evil.', example: 'The court described the crime as heinous and awarded the maximum sentence.', synonyms: ['atrocious', 'monstrous', 'abominable']),
  EnglishWord(word: 'Hereby', partOfSpeech: 'adverb', definition: 'As a result of this document or statement; by this means.', example: 'It is hereby ordered that the respondent shall pay the decreed amount within 30 days.', synonyms: ['by this', 'by means of this']),
  EnglishWord(word: 'Hereinafter', partOfSpeech: 'adverb', definition: 'From this point on in this document.', example: 'M/s ABC Pvt Ltd, hereinafter referred to as the "Company".', synonyms: ['henceforth', 'from now on']),
  EnglishWord(word: 'Hypothetical', partOfSpeech: 'adjective', definition: 'Based on an assumed or supposed situation rather than fact.', example: 'The court cannot decide hypothetical questions not arising from the facts.', synonyms: ['theoretical', 'assumed', 'speculative']),

