  EnglishWord(word: 'Illicit', partOfSpeech: 'adjective', definition: 'Forbidden by law, rules, or custom; unlawful.', example: 'The accused was caught trafficking in illicit narcotics.', synonyms: ['illegal', 'unlawful', 'prohibited']),
  EnglishWord(word: 'Immutable', partOfSpeech: 'adjective', definition: 'Unchanging over time; not able to be changed.', example: 'The basic structure of the Constitution is immutable and cannot be amended.', synonyms: ['unchangeable', 'fixed', 'permanent']),
