  EnglishWord(word: 'Inalienable', partOfSpeech: 'adjective', definition: 'Unable to be taken away from or given away by the possessor.', example: 'The right to life is an inalienable right guaranteed by the Constitution.', synonyms: ['inviolable', 'absolute', 'inherent']),
  EnglishWord(word: 'Incidental', partOfSpeech: 'adjective', definition: 'Occurring by chance in connection with something else; minor.', example: 'The court also has power to pass incidental orders necessary for doing complete justice.', synonyms: ['secondary', 'ancillary', 'subsidiary']),
  EnglishWord(word: 'Incontrovertible', partOfSpeech: 'adjective', definition: 'Not able to be denied or disputed; undeniable.', example: 'The documentary evidence was incontrovertible proof of the transaction.', synonyms: ['indisputable', 'undeniable', 'irrefutable']),
  EnglishWord(word: 'Incriminate', partOfSpeech: 'verb', definition: 'To make someone appear guilty of a crime or wrongdoing.', example: 'No person shall be compelled to be a witness against himself or to incriminate himself.', synonyms: ['implicate', 'accuse', 'charge']),
  EnglishWord(word: 'Indemnify', partOfSpeech: 'verb', definition: 'To compensate for harm or loss; to secure against legal liability.', example: 'The insurance company is bound to indemnify the policyholder against losses.', synonyms: ['compensate', 'reimburse', 'insure']),
