  EnglishWord(word: 'Infirmity', partOfSpeech: 'noun', definition: 'Physical or mental weakness; a defect or flaw.', example: 'The High Court found no infirmity in the trial court\'s judgment.', synonyms: ['weakness', 'defect', 'flaw']),
  EnglishWord(word: 'Infringe', partOfSpeech: 'verb', definition: 'To actively break the terms of a law or agreement; to violate.', example: 'The executive order infringes upon the fundamental right to free speech.', synonyms: ['violate', 'breach', 'transgress']),
  EnglishWord(word: 'Inherent', partOfSpeech: 'adjective', definition: 'Existing as an essential constituent or characteristic; intrinsic.', example: 'The High Court exercises inherent powers under Section 482 CrPC to prevent abuse of process.', synonyms: ['intrinsic', 'innate', 'built-in']),
