  EnglishWord(word: 'Instigate', partOfSpeech: 'verb', definition: 'To bring about or initiate an action or event; to provoke.', example: 'He was charged with instigating the riot by delivering inflammatory speeches.', synonyms: ['incite', 'provoke', 'initiate']),
  EnglishWord(word: 'Inviolable', partOfSpeech: 'adjective', definition: 'Never to be broken, infringed, or dishonoured; sacrosanct.', example: 'The secular character of the Constitution is inviolable and forms part of its basic structure.', synonyms: ['sacrosanct', 'sacred', 'untouchable']),
