  // ═══ J ═══
  EnglishWord(word: 'Jeopardize', partOfSpeech: 'verb', definition: 'To put at risk of being harmed or lost; to endanger.', example: 'Delay in trial jeopardizes the accused\'s right to a speedy trial.', synonyms: ['endanger', 'risk', 'imperil']),
