  EnglishWord(word: 'Jurisdiction', partOfSpeech: 'noun', definition: 'The official power to make legal decisions and judgments; the extent of that power.', example: 'The civil court has no jurisdiction to try the matter which falls within the revenue court\'s domain.', synonyms: ['authority', 'power', 'competence']),
  EnglishWord(word: 'Jurisprudence', partOfSpeech: 'noun', definition: 'The theory or philosophy of law; a legal system.', example: 'Indian jurisprudence has evolved significantly on the right to privacy.', synonyms: ['legal theory', 'philosophy of law']),
  EnglishWord(word: 'Justify', partOfSpeech: 'verb', definition: 'To show or prove to be right or reasonable; to provide adequate grounds.', example: 'The circumstances did not justify the imposition of the death penalty.', synonyms: ['validate', 'vindicate', 'substantiate']),

  // ═══ K ═══
  EnglishWord(word: 'Kinship', partOfSpeech: 'noun', definition: 'Blood relationship; the sharing of characteristics or origins.', example: 'Kinship ties determine the order of succession in Hindu law.', synonyms: ['relationship', 'affinity', 'bond']),

