  EnglishWord(word: 'Lapse', partOfSpeech: 'verb/noun', definition: 'To expire or become void through disuse or failure to act.', example: 'The appeal lapsed as it was not filed within the prescribed period of limitation.', synonyms: ['expire', 'void', 'elapse']),
