  EnglishWord(word: 'Malice', partOfSpeech: 'noun', definition: 'The intention or desire to do evil; ill will.', example: 'The prosecution must prove malice aforethought for a conviction of murder.', synonyms: ['spite', 'ill will', 'animosity']),
