  EnglishWord(word: 'Manifest', partOfSpeech: 'adjective/verb', definition: 'Clear or obvious to the eye or mind; to display or demonstrate.', example: 'The error in the judgment was manifest on the face of the record.', synonyms: ['obvious', 'evident', 'apparent']),
  EnglishWord(word: 'Mediate', partOfSpeech: 'verb', definition: 'To intervene in a dispute to bring about an agreement.', example: 'The retired judge was appointed to mediate between the disputing parties.', synonyms: ['arbitrate', 'negotiate', 'intercede']),
