  EnglishWord(word: 'Mitigate', partOfSpeech: 'verb', definition: 'To make less severe, serious, or painful.', example: 'The accused\'s age and lack of prior record were considered as mitigating factors.', synonyms: ['alleviate', 'reduce', 'diminish']),
  EnglishWord(word: 'Moot', partOfSpeech: 'adjective', definition: 'Subject to debate; having no practical significance (in US law: academic).', example: 'The question has become moot as the impugned order has already been implemented.', synonyms: ['debatable', 'academic', 'arguable']),
  EnglishWord(word: 'Muster', partOfSpeech: 'verb', definition: 'To assemble or gather; to summon up a quality or feeling.', example: 'The prosecution failed to muster sufficient evidence for conviction.', synonyms: ['gather', 'assemble', 'summon']),

  // ═══ N ═══
  EnglishWord(word: 'Nascent', partOfSpeech: 'adjective', definition: 'Just beginning to develop; not yet fully formed.', example: 'India\'s data protection framework is still in its nascent stage.', synonyms: ['emerging', 'developing', 'budding']),
  EnglishWord(word: 'Negligence', partOfSpeech: 'noun', definition: 'Failure to take proper care; carelessness leading to damage or injury.', example: 'Medical negligence was established as the surgeon failed to follow standard protocol.', synonyms: ['carelessness', 'inattention', 'laxity']),
  EnglishWord(word: 'Nominal', partOfSpeech: 'adjective', definition: 'In name only; very small or token.', example: 'Nominal damages of Re. 1 were awarded to acknowledge the violation of rights.', synonyms: ['token', 'symbolic', 'minimal']),
  EnglishWord(word: 'Notarize', partOfSpeech: 'verb', definition: 'To have a document officially authenticated by a notary public.', example: 'The affidavit must be notarized before it can be filed in court.', synonyms: ['authenticate', 'certify', 'attest']),
  EnglishWord(word: 'Nullify', partOfSpeech: 'verb', definition: 'To make legally null and void; to invalidate.', example: 'The Supreme Court nullified the legislation as unconstitutional.', synonyms: ['invalidate', 'void', 'annul']),

  // ═══ O ═══
  EnglishWord(word: 'Obligatory', partOfSpeech: 'adjective', definition: 'Required by a legal, moral, or other rule; compulsory.', example: 'Registration of the sale deed is obligatory under the Registration Act.', synonyms: ['compulsory', 'mandatory', 'required']),
  EnglishWord(word: 'Obstruct', partOfSpeech: 'verb', definition: 'To block or impede; to deliberately make difficult.', example: 'Obstructing a public servant in the discharge of duties is a punishable offence.', synonyms: ['block', 'hinder', 'impede']),
  EnglishWord(word: 'Onerous', partOfSpeech: 'adjective', definition: 'Involving an amount of effort that is oppressively burdensome.', example: 'The conditions imposed on the bail were unduly onerous.', synonyms: ['burdensome', 'oppressive', 'demanding']),
  EnglishWord(word: 'Onus', partOfSpeech: 'noun', definition: 'The burden of proof or responsibility.', example: 'The onus of proving the guilt of the accused lies on the prosecution.', synonyms: ['burden', 'responsibility', 'duty']),
