  EnglishWord(word: 'Presume', partOfSpeech: 'verb', definition: 'To suppose that something is the case on the basis of probability; to take for granted.', example: 'Every accused person is presumed innocent until proven guilty.', synonyms: ['assume', 'suppose', 'take for granted']),
