  EnglishWord(word: 'Propriety', partOfSpeech: 'noun', definition: 'The state or quality of conforming to conventionally accepted standards of behavior.', example: 'The propriety of the judge\'s conduct was questioned in the transfer petition.', synonyms: ['decorum', 'appropriateness', 'correctness']),
  EnglishWord(word: 'Prosecute', partOfSpeech: 'verb', definition: 'To institute legal proceedings against someone in a criminal court.', example: 'The State decided to prosecute the officials for dereliction of duty.', synonyms: ['charge', 'try', 'indict']),
