  EnglishWord(word: 'Punitive', partOfSpeech: 'adjective', definition: 'Inflicting or intended as punishment.', example: 'The court awarded punitive damages to deter the defendant from future misconduct.', synonyms: ['penalizing', 'disciplinary', 'retributive']),

  // ═══ Q ═══
  EnglishWord(word: 'Quash', partOfSpeech: 'verb', definition: 'To reject or void, especially by legal procedure; to suppress.', example: 'The High Court quashed the FIR filed against the petitioner.', synonyms: ['annul', 'void', 'overturn']),
  EnglishWord(word: 'Quasi', partOfSpeech: 'adjective', definition: 'Seemingly; apparently but not really; having some resemblance.', example: 'The tribunal functions as a quasi-judicial body with the power to decide disputes.', synonyms: ['seeming', 'apparent', 'pseudo']),

