  EnglishWord(word: 'Recalcitrant', partOfSpeech: 'adjective', definition: 'Having an obstinately uncooperative attitude towards authority.', example: 'The recalcitrant witness was warned of contempt proceedings.', synonyms: ['obstinate', 'defiant', 'uncooperative']),
  EnglishWord(word: 'Recourse', partOfSpeech: 'noun', definition: 'A source of help in a difficult situation; the use of a legal right.', example: 'The aggrieved party has recourse to the appellate tribunal.', synonyms: ['resort', 'remedy', 'option']),
  EnglishWord(word: 'Redress', partOfSpeech: 'noun/verb', definition: 'Remedy or compensation for a wrong or grievance.', example: 'The petitioner seeks redress for the violation of her fundamental rights.', synonyms: ['remedy', 'reparation', 'compensation']),
  EnglishWord(word: 'Refute', partOfSpeech: 'verb', definition: 'To prove a statement or theory to be wrong or false.', example: 'The defence successfully refuted the allegation of conspiracy.', synonyms: ['disprove', 'rebut', 'deny']),
