  EnglishWord(word: 'Remuneration', partOfSpeech: 'noun', definition: 'Money paid for work or a service; compensation.', example: 'The advocate\'s remuneration shall be fixed by the court as per the schedule.', synonyms: ['payment', 'compensation', 'salary']),
  EnglishWord(word: 'Repeal', partOfSpeech: 'verb/noun', definition: 'To revoke or annul a law or act of parliament.', example: 'Article 370 was effectively repealed through a constitutional amendment.', synonyms: ['revoke', 'rescind', 'abrogate']),
  EnglishWord(word: 'Reprehensible', partOfSpeech: 'adjective', definition: 'Deserving censure or condemnation; shameful.', example: 'The court termed the custodial violence as reprehensible and unacceptable.', synonyms: ['deplorable', 'disgraceful', 'blameworthy']),
  EnglishWord(word: 'Repudiate', partOfSpeech: 'verb', definition: 'To refuse to accept or fulfill; to deny the truth of.', example: 'The promisor repudiated the contract before the date of performance.', synonyms: ['reject', 'deny', 'disown']),
